19. 다음 파이썬 프로그램의 실행 결과는?
cnt = 0
class Node:
def __init__(self,key,h,lf = None,rg = None):
self.key = key
self.h = h
self.lf = lf
self.rg = rg
class TREE:
def __init__(self):
self.r = None
def h(self, n):
if n == None:
return 0
return n.h
def put(self, key):
self.r = self.putitem(self.r,key)
def putitem(self, n, key):
if n == None:
return Node(key, 1)
if n.key > key:
n.lf = self.putitem(n.lf,key)
elif n.key < key:
n.rg = self.putitem(n.rg,key)
else:
return n
n.h = max(self.h(n.lf),self.h(n.rg)) + 1
return self.bal(n)
def bal(self, n):
global cnt
if self.bf(n) > 1:
if self.bf(n.lf) < 0:
n.lf = self.lf(n.lf)
cnt += 1
n = self.rg(n)
cnt += 1
elif self.bf(n) < -1:
if self.bf(n.rg) > 0:
n.rg = self.rg(n.rg)
cnt += 1
n = self.lf(n)
cnt += 1
return n
def rg(self, j):
i = j.lf
j.lf = i.rg
i.rg = j
j.h = max(self.h(j.lf),self.h(j.rg)) + 1
i.h = max(self.h(i.lf),self.h(i.rg)) + 1
return i
def lf(self, j):
i = j.rg
j.rg = i.lf
i.lf = j
j.h = max(self.h(j.lf),self.h(j.rg)) + 1
i.h = max(self.h(i.lf),self.h(i.rg)) + 1
return i
def bf(self, n):
return self.h(n.lf) - self.h(n.rg)
if __name__ == '__main__':
t = TREE()
value = [5, 22, 3, 14, 2, 19]
for i in value:
t.put(i)
print(cnt)
①1
②2
③3
④4

25. 다음 파이썬 프로그램의 실행 결과는?
class NodeBS(object):
def __init__(self, vl = None):
self.vl = vl
self.root = None
self.lf = None
self.rg = None
def _ad(self, vl):
nd = NodeBS(vl)
if vl > self.vl:
self.rg = self.rg and self.rg._ad(vl) or nd
elif vl < self.vl:
self.lf = self.lf and self.lf._ad(vl) or nd
else:
print("node duplicated")
return self
class Bst(NodeBS):
def add_node(self, vl):
if not self.root:
self.root = NodeBS(vl)
else:
self.root._ad(vl)
def order(self):
current = self.root
nodes, stack = [], []
while stack or current:
if current:
nodes.append(current.vl)
stack.append(current)
current = current.lf
else:
current = stack.pop()
current = current.rg
return nodes
if __name__ == "__main__":
bt = Bst()
in_list = [6, 4, 8, 2, 5, 7, 9, 1, 3, 10]
for i in in_list:
bt.add_node(i)
print(bt.order())
